/* Dictionnaire FR → IT du jeu (voir assets/i18n/i18n.js). Clé = texte
   français tel qu'affiché ({0}, {player}… = parties variables), valeur =
   italien. Mêmes clés que en.js : `node scripts/i18n_missing.js it` liste
   les clés présentes dans en.js mais absentes ici (à traduire après un merge).

   Glossaire (à respecter dans tout le fichier) :
   - Tableau de bord → Panoramica ; Effectif → Rosa ; Ordres → Ordini ;
     Calendrier → Calendario ; Ligue → Lega ; Classement → Classifica ;
     Coupe → Coppa ; Amicaux → Amichevoli ; Marché → Mercato ;
     Entraînement → Allenamento ; Tactiques → Tattiche ; Économie → Economia ;
     Salle → Palazzetto ; Supporters → Tifosi ; Personnalisation →
     Personalizzazione ; Guide → Guida ; Académie → Vivaio (Académie de
     jeunes → Settore giovanile) ; Centre de formation → Centro di formazione ;
     Paramètres → Impostazioni ; onglet → scheda.
   - Postes : Meneur → Playmaker (PM) ; Arrière → Guardia (G) ; Ailier
     shooteur → Ala piccola (AP) ; Ailier fort → Ala grande (AG) ; Pivot →
     Centro (C). Poste → Ruolo.
   - Stats : points → punti (pti) ; rebonds → rimbalzi (rimb) ; passes
     décisives → assist (ass) ; contres → stoppate (stp) ; interceptions →
     palle rubate (rub) ; balles perdues → palle perse (PP) ; lancers francs →
     tiri liberi (TL) ; tir à 3 points → tiro da tre / tripla ; fautes → falli ;
     évaluation → valutazione (Val) ; V/D → V/S ; J (journée) → G (giornata).
   - Match → partita ; coup d'envoi → palla a due ; mi-temps → intervallo /
     tempo ; quart-temps → quarto ; prolongation → supplementare ; temps mort
     → timeout ; titulaire → titolare ; remplaçant → riserva ; réserviste →
     riservista ; cinq de départ → quintetto iniziale ; convocation →
     convocazione ; feuille de match → tabellino (formazione quand il s'agit
     de la composition) ; forfait → a tavolino ; barrage → spareggio ;
     maintien → salvezza ; relégation → retrocessione ; montée → promozione ;
     titre de champion → scudetto ; play-offs → playoff.
   - Enchère → asta / offerta ; masse salariale → monte ingaggi ; salaire →
     stipendio ; recrutement / recruteur → ingaggio / osservatore ; analyste
     vidéo → video analista ; entraîneur adjoint → vice allenatore ; kiné →
     fisioterapista ; alchimie → intesa ; humeur → umore ; forme physique →
     condizione fisica ; palier → livello ; trigramme → sigla ; Espoir /
     Grand espoir / Prodige → Promessa / Grande promessa / Prodigio ;
     Débutant / Confirmé (niveau tactique) → Principiante / Esperto ;
     intersaison → pausa estiva ; succès (manager) → traguardi.
   - On tutoie le joueur (« tu »), comme la page d'accueil. Les noms propres
     (joueurs, sponsors fictifs de marque, divisions I, II.1…) restent tels
     quels ; les nombres suivent l'usage italien (1.234 ; 12,5). */
