  "Note de départ 1500, qui monte ou descend à chaque match officiel contre un autre manager (plus l'adversaire est bien noté, plus la victoire rapporte). Les matchs contre l'IA et les amicaux ne comptent pas. {0} manager classé.": "Punteggio di partenza 1500, che sale o scende a ogni partita ufficiale contro un altro manager (più l'avversario ha un punteggio alto, più la vittoria rende). Le partite contro l'IA e le amichevoli non contano. {0} manager in classifica.",
  "Note de départ 1500, qui monte ou descend à chaque match officiel contre un autre manager (plus l'adversaire est bien noté, plus la victoire rapporte). Les matchs contre l'IA et les amicaux ne comptent pas. {0} managers classés.": "Punteggio di partenza 1500, che sale o scende a ogni partita ufficiale contro un altro manager (più l'avversario ha un punteggio alto, più la vittoria rende). Le partite contro l'IA e le amichevoli non contano. {0} manager in classifica.",
  "Le classement se départage par victoires puis par différence de points. Places 1 à 4 : play-offs. Barrage et relégation seulement s'il existe un championnat juste en dessous (couleurs et légende l'indiquent). Ce panneau résume votre position et l'écart avec les places clés.": "La classifica si decide per vittorie e poi per differenza punti. Posti da 1 a 4: playoff. Spareggio e retrocessione solo se esiste un campionato subito sotto (lo indicano i colori e la legenda). Questo pannello riassume la tua posizione e il distacco dai posti chiave.",
