  ", 5 et 6 maintien direct, 7 et 8": ", 5º e 6º salvi direttamente, 7º e 8º",
  ", agrandissable palier par palier depuis cet onglet, accélère cette progression. À ses 18 ans, une décision est requise pour chaque jeune : le promouvoir dans l'effectif pro (il dévoile alors son vrai palier de potentiel) ou le libérer définitivement. Sans décision avant la saison suivante, il est automatiquement libéré. L'historique des jeunes promus reste visible en bas de la page.": ", ampliabile livello per livello da questa scheda, accelera questa crescita. A 18 anni serve una decisione per ogni giovane: promuoverlo in prima squadra (rivela allora il suo vero livello di potenziale) o svincolarlo definitivamente. Senza decisione prima della stagione successiva, viene svincolato automaticamente. Lo storico dei giovani promossi resta visibile in fondo alla pagina.",
  ", au moment où commence l'émission d'avant-match.": ", quando inizia il programma prepartita.",
  "d'abord (liseré orange et petit « 5 »), puis la rotation, puis la réserve (nom estompé), d'après la feuille de match actuelle ; cliquez un titre de colonne pour trier toute la liste. Pour chacun : poste, potentiel, âge, taille, salaire, forme, motivation et évaluation des derniers matchs. Le menu": "prima (bordo arancione e piccolo «5»), poi la rotazione, poi le riserve (nome attenuato), secondo il tabellino attuale; clicca sul titolo di una colonna per ordinare tutta la lista. Per ognuno: ruolo, potenziale, età, altezza, stipendio, forma, motivazione e valutazione delle ultime partite. Il menu",
  ", de plus en plus vite si vous la gardez plusieurs matchs de suite : +6, +8, +10, puis +12 par match. L'entraînement collectif": ", sempre più in fretta se la mantieni per più partite di fila: +6, +8, +10, poi +12 a partita. L'allenamento collettivo",
  ", du plus modeste au plus rare :": ", dal più modesto al più raro:",
  ", gérer l'": ", gestire il",
  ", le {0}": ", il {0}",
  ", mais doucement : rien les 2 premiers matchs d'absence, puis -2, -4 et au maximum -6 par match. Revenir à une tactique délaissée la fait remonter progressivement, jamais d'un coup.": ", ma dolcemente: niente nelle prime 2 partite di assenza, poi -2, -4 e al massimo -6 a partita. Tornare a una tattica trascurata la fa risalire gradualmente, mai di colpo.",
  ", mais ils le prennent moins que d'autres zones.": ", ma lo prendono meno di altre zone.",
  ", Mécontents": ", Scontenti",
  ", plus floue, alignée sur les mêmes paliers :": ", più sfocata, allineata sugli stessi livelli:",
