  "\"Ça fait des semaines que je suis sur le banc sans la moindre explication, je demande à partir\", lâche {player}.": "\"Sono settimane che sto in panchina senza la minima spiegazione, chiedo di andare via\", sbotta {player}.",
  "\"J'ai besoin de retrouver du temps de jeu ailleurs\", déclare {player}, visiblement lassé de la situation.": "\"Ho bisogno di ritrovare minuti altrove\", dichiara {player}, visibilmente stanco della situazione.",
  "\"Je ne me sens plus utile ici, il est temps d'envisager un nouveau projet\", confie {player} à la presse.": "\"Non mi sento più utile qui, è ora di pensare a un nuovo progetto\", confida {player} alla stampa.",
  "\"Le club connaît ma position, je souhaite être transféré au plus vite\", affirme {player}.": "\"Il club conosce la mia posizione, voglio essere ceduto il prima possibile\", afferma {player}.",
  "« À mi-parcours, cette victoire contre Adversaire test confirme qu'on est sur la bonne trajectoire, il reste encore la moitié de la saison pour la confirmer. On va continuer à travailler dans la continuité, avec quelques ajustements tactiques pour la seconde moitié. »": "« A metà percorso, questa vittoria contro Avversario test conferma che siamo sulla strada giusta, resta ancora metà stagione per confermarlo. Continueremo a lavorare nella continuità, con qualche ritocco tattico per la seconda metà. »",
  "« Comme l'appareil » suit le mode clair ou sombre de ton ordinateur ou de ton téléphone.": "« Come il dispositivo » segue la modalità chiara o scura del tuo computer o del tuo telefono.",
  "({0}-{1}, en cours)": "({0}-{1}, in corso)",
  "({1} pts) et": "({1} pti) e",
  "({1}) · {2} d'efficacité sur {3}": "({1}) · {2} di efficacia su {3}",
  "({3} pts).": "({3} pti).",
  "(aux deux niveaux) : Standard garde le comportement habituel. Adaptatif ajoute un vrai garbage time dès 10 points d'écart à partir du 3e quart-temps (au 4e quart-temps, à 18 points d'écart, les titulaires sortent pour ménager leur forme), et accélère légèrement le rythme dans les 5 dernières minutes d'un match serré.": "(a entrambi i livelli): Standard mantiene il comportamento abituale. Adattivo aggiunge un vero garbage time da 10 punti di scarto a partire dal 3º quarto (nel 4º quarto, con 18 punti di scarto, i titolari escono per preservare la forma), e accelera leggermente il ritmo negli ultimi 5 minuti di una partita equilibrata.",
  "(avec une petite jauge à 10 crans dans l'Effectif ; survolez le nom du palier pour voir son rang de 1 à 10). Un jeune joueur encore faible mais à fort potentiel peut, bien entraîné, dépasser largement un joueur déjà bon dont le potentiel est presque atteint.": "(con un piccolo indicatore a 10 tacche nella Rosa; passa sopra il nome del livello per vederne il grado da 1 a 10). Un giovane ancora debole ma con alto potenziale può, se ben allenato, superare di gran lunga un giocatore già buono il cui potenziale è quasi raggiunto.",
  "(c'est vous !)": "(sei tu!)",
  "(cinq moments clés de la saison : début, mi-saison, fin de saison régulière, demi-finale puis finale des play-offs). Chaque interview pose deux questions, avec un ton à choisir pour chacune : Agressif amplifie le résultat (meilleur gain en cas de victoire, pire perte en cas de défaite), Mesuré reste sûr et modéré, Humble plafonne le gain en cas de victoire mais est le seul ton qui tourne une défaite en effet positif. Toute l'équipe est concernée. Ignorer l'interview (possible pendant 3 jours) n'a aucun effet. Un remplaçant qui ne joue quasiment jamais perd un peu de motivation chaque semaine, davantage s'il est meilleur que le titulaire de son poste.": "(cinque momenti chiave della stagione: inizio, metà stagione, fine della stagione regolare, semifinale e poi finale playoff). Ogni intervista pone due domande, con un tono da scegliere per ciascuna: Aggressivo amplifica il risultato (guadagno maggiore in caso di vittoria, perdita peggiore in caso di sconfitta), Misurato resta sicuro e moderato, Umile limita il guadagno in caso di vittoria ma è l'unico tono che trasforma una sconfitta in un effetto positivo. Riguarda tutta la squadra. Ignorare l'intervista (possibile per 3 giorni) non ha alcun effetto. Una riserva che non gioca quasi mai perde un po' di motivazione ogni settimana, di più se è migliore del titolare del suo ruolo.",
  "(display-mode: standalone)": "(display-mode: standalone)",
  "(Division {0})": "(Divisione {0})",
