  "29 caractéristiques (0 à 99) : Tir à mi-distance, Tir à 3 points, Jeu intérieur, Passe, Rebond, Contre, Dribble, Agilité, Défense extérieure, Défense intérieure, Mental, Endurance, Lancer franc, Pénétration, Création de tir, Interceptions, Puissance, Concentration, Anticipation, Leadership, Vitesse, Accélération, Force, Détente, Décision, Sang-froid, Détermination, Discipline et Vision. Sur chacune, plus le chiffre est élevé, mieux c'est, sans exception. La couleur donne le niveau en un coup d'œil : rouge en dessous de 45, grise de 45 à 64, verte de 65 à 79, dorée à partir de 80 (niveau élite).": "29 caratteristiche (da 0 a 99): Tiro dalla media, Tiro da 3 punti, Gioco interno, Passaggio, Rimbalzo, Stoppata, Palleggio, Agilità, Difesa perimetrale, Difesa interna, Mentale, Resistenza, Tiro libero, Penetrazione, Creazione del tiro, Palle rubate, Potenza, Concentrazione, Anticipo, Leadership, Velocità, Accelerazione, Forza, Elevazione, Decisioni, Sangue freddo, Determinazione, Disciplina e Visione. Per ognuna, più il numero è alto, meglio è, senza eccezioni. Il colore indica il livello a colpo d'occhio: rosso sotto 45, grigio da 45 a 64, verde da 65 a 79, oro da 80 in su (livello élite).",
