  "Agrandissez votre salle place par place pour accueillir plus de spectateurs (brique Agrandir la salle : chaque type de gradin a son prix par place et son nombre maximum de places), et réglez le prix du billet CATÉGORIE PAR CATÉGORIE : gradins populaires, tribune couverte et loges VIP n'ont ni la même capacité, ni la même tolérance au prix. Seuls les matchs à domicile rapportent une recette. L'humeur des supporters influence le remplissage et la tolérance au prix. D'autres infrastructures sont proposées, chacune sur 4 paliers : Station TV (revenu fixe chaque semaine), Salle de musculation (réduit le risque de blessure) et Espace bien-être (réduit la fatigue en match).": "Amplia il tuo palazzetto posto per posto per accogliere più spettatori (riquadro Amplia il palazzetto: ogni tipo di tribuna ha il suo prezzo per posto e il suo numero massimo di posti), e imposta il prezzo del biglietto SETTORE PER SETTORE: gradinate popolari, tribuna coperta e palchi VIP non hanno né la stessa capienza né la stessa tolleranza al prezzo. Solo le partite in casa portano incassi. L'umore dei tifosi influisce sul riempimento e sulla tolleranza al prezzo. Sono disponibili altre strutture, ciascuna su 4 livelli: Stazione TV (entrata fissa ogni settimana), Sala pesi (riduce il rischio di infortunio) e Area benessere (riduce la stanchezza in partita).",
