  "Avant chaque match, réglez trois choses pour votre équipe dans l'onglet Ordres. Tout s'enregistre automatiquement à chaque changement, et le bouton \"Enregistrer\", toujours visible en bas de la page, confirme l'enregistrement (\"Annuler\" revient aux ordres tels qu'à l'ouverture de la page). Dans le Calendrier, un match aux ordres validés affiche \"Modifier vos ordres\".": "Prima di ogni partita, imposta tre cose per la tua squadra nella scheda Ordini. Tutto si salva automaticamente a ogni modifica, e il pulsante \"Salva\", sempre visibile in fondo alla pagina, conferma il salvataggio (\"Annulla\" riporta agli ordini com'erano all'apertura della pagina). Nel Calendario, una partita con ordini confermati mostra \"Modifica i tuoi ordini\".",
