  "Budget disponible": "Budget disponibile",
  "Budget du club": "Budget del club",
  "Budget du club et son évolution, masse salariale (joueurs et staff), revenus de la salle, de la boutique et des droits TV, et l'historique des transactions groupé par semaine. Un budget durablement sous le seuil d'alerte finit par mettre tout l'effectif en vente forcée à 1 € : surveillez la masse salariale.": "Budget del club e sua evoluzione, monte ingaggi (giocatori e staff), entrate del palazzetto, del negozio e dei diritti TV, e storico delle transazioni raggruppato per settimana. Un budget che resta a lungo sotto la soglia d'allarme finisce per mettere tutta la rosa in vendita forzata a 1 €: tieni d'occhio il monte ingaggi.",
  "Budget initial : {0}": "Budget iniziale: {0}",
