  "C’est bientôt l’heure ! Bon match à tous.": "Manca poco! Buona partita a tutti.",
  "C'est lui qui fait remonter des prospects de 15 à 17 ans : sans recruteur, aucun jeune ne vous sera proposé.": "È lui che ti segnala i prospetti dai 15 ai 17 anni: senza osservatore, non ti verrà proposto nessun giovane.",
