  "Changement de couleurs de maillot extérieur refusé côté serveur.": "Cambio dei colori della maglia da trasferta rifiutato dal server.",
  "Changement de couleurs de maillot refusé côté serveur.": "Cambio dei colori della maglia rifiutato dal server.",
