  "Changement de maillot refusé côté serveur.": "Cambio della maglia rifiutato dal server.",
  "Changement de motif de maillot extérieur refusé côté serveur.": "Cambio del motivo della maglia da trasferta rifiutato dal server.",
  "Changement de motif de maillot refusé côté serveur.": "Cambio del motivo della maglia rifiutato dal server.",
  "Changement de statut club refusé côté serveur.": "Cambio dello stato del club rifiutato dal server.",
  "Changer d'analyste vidéo": "Cambia video analista",
  "Changer d'entraîneur": "Cambia allenatore",
  "Changer de recruteur": "Cambia osservatore",
  "Changer le logo": "Cambia il logo",
  "Chaque annonce compare le prix à une valeur estimée (Bonne affaire, Prix correct, Au-dessus de sa valeur). Une enchère gagnée s'ajoute immédiatement à votre masse salariale : vérifiez votre budget avant de vous engager.": "Ogni annuncio confronta il prezzo con un valore stimato (Affare, Prezzo giusto, Sopra il suo valore). Un'asta vinta si aggiunge subito al tuo monte ingaggi: controlla il budget prima di impegnarti.",
  "Chaque changement est déjà enregistré automatiquement. « Enregistrer » confirme l'enregistrement auprès du serveur.": "Ogni modifica è già salvata automaticamente. « Salva » conferma il salvataggio sul server.",
  "à chaque jour de repos (jour sans match) : soit préparer une nouvelle tactique, soit privilégier la récupération physique de l'équipe.": "a ogni giorno di riposo (giorno senza partita): preparare una nuova tattica oppure privilegiare il recupero fisico della squadra.",
  "Le club choisit": "Il club sceglie",
  "Chaque jour, le club travaille un programme parmi les 13 fondamentaux (tir à 3 points, rebond, défense extérieure...) et un ou plusieurs postes à qui l'appliquer. Cibler un seul poste donne le plein rendement ; l'étendre à toute l'équipe touche plus de joueurs mais dilue l'effet. Le Physique et le Mental évoluent, eux, tout seuls au fil de la carrière, indépendamment de ce programme.": "Ogni giorno il club lavora su un programma tra i 13 fondamentali (tiro da 3 punti, rimbalzo, difesa perimetrale...) e uno o più ruoli a cui applicarlo. Puntare su un solo ruolo dà il pieno rendimento; estenderlo a tutta la squadra coinvolge più giocatori ma diluisce l'effetto. Il Fisico e il Mentale, invece, evolvono da soli nel corso della carriera, indipendentemente da questo programma.",
  "Chaque match se joue à son heure, que vous le regardiez ou non. Connecté, suivez-le depuis l'onglet": "Ogni partita si gioca al suo orario, che tu la guardi o no. Se sei connesso, seguila dalla scheda",
  "Chaque nom de club doit être une chaîne non vide.": "Ogni nome di club deve essere una stringa non vuota.",
  "Chaque prospect affiche une estimation de potentiel (Espoir, Grand espoir ou Prodige) et se signe directement, sans enchère ni négociation, contrairement au marché des transferts.": "Ogni prospetto mostra una stima del potenziale (Promessa, Grande promessa o Prodigio) e si ingaggia direttamente, senza asta né trattativa, a differenza del mercato dei trasferimenti.",
  "Chaque variation d'ambiance est journalisée ici avec son motif exact : résultat de match, prix du billet, interview de jalon, demande de transfert, signal ou verdict d'objectif de saison.": "Ogni variazione dell'atmosfera è registrata qui con la sua causa esatta: risultato della partita, prezzo del biglietto, intervista chiave, richiesta di cessione, segnale o verdetto dell'obiettivo stagionale.",
