  "Congédier": "Licenzia",
  "Connaissance tactique": "Conoscenza tattica",
  "Connaissance tactique : chaque option jouée monte de +6 à +12 par match, +4 par jour d'entraînement dessus ; une option délaissée ne baisse qu'à partir du 3e match d'absence (-2, -4, puis -6 au maximum). Le détail est dans le Guide.": "Conoscenza tattica: ogni opzione giocata sale da +6 a +12 a partita, +4 per ogni giorno di allenamento su di essa; un'opzione trascurata inizia a calare solo dalla 3ª partita di assenza (-2, -4, poi -6 al massimo). Il dettaglio è nella Guida.",
  "Conseil : attaquez la raquette sans crainte, pénétrez et finissez au panier plutôt que de vous contenter du tir extérieur.": "Consiglio: attacca l'area senza paura, penetra e chiudi al ferro invece di accontentarti del tiro da fuori.",
  "Conseil : envoyez du monde au rebond offensif, les secondes chances seront disponibles.": "Consiglio: manda uomini a rimbalzo offensivo, le seconde occasioni ci saranno.",
  "Conseil : évitez la finition en force au cercle, privilégiez le tir extérieur ou la passe après pénétration (kick-out) plutôt que le layup contesté.": "Consiglio: evita di forzare al ferro, preferisci il tiro da fuori o lo scarico dopo la penetrazione (kick-out) al layup contestato.",
  "Conseil : forcez la pénétration balle en main et jouez agressif vers le cercle pour provoquer des fautes et aller sur la ligne des lancers francs.": "Consiglio: forza la penetrazione palla in mano e gioca aggressivo verso il ferro per procurarti falli e andare in lunetta.",
  "Conseil : ne comptez pas sur les lancers francs, il faudra scorer au jeu plutôt que provoquer la faute.": "Consiglio: non contare sui tiri liberi, dovrai segnare su azione invece di procurarti il fallo.",
  "Conseil : ne surinvestissez pas le rebond offensif, repliez-vous plus tôt pour limiter leur contre-attaque.": "Consiglio: non investire troppo sul rimbalzo offensivo, rientra prima in difesa per limitare il loro contropiede.",
  "Conseil : sécurisez la balle et limitez les passes risquées pour ne pas les lancer en contre-attaque.": "Consiglio: proteggi la palla e limita i passaggi rischiosi per non lanciarli in contropiede.",
