  "Contrôlé": "Controllato",
  "Contrôlé est le réglage neutre. Agressif conteste mieux les tirs extérieurs réellement pris, mais une fermeture trop appuyée ouvre plus facilement la pénétration : le tireur en profite pour foncer vers le panier plutôt que de tirer.": "Controllato è l'impostazione neutra. Aggressivo contesta meglio i tiri da fuori effettivamente presi, ma una chiusura troppo decisa apre più facilmente la penetrazione: il tiratore ne approfitta per attaccare il canestro invece di tirare.",
