  "dans l'onglet Staff pour faire remonter des prospects de 15 à 17 ans (une file de candidats propre à votre club, renouvelée régulièrement ; une proposition non traitée expire). Chaque candidat s'affiche en carte avec son estimation de potentiel (Espoir, Grand espoir ou Prodige, voir": "nella scheda Staff per far arrivare prospetti dai 15 ai 17 anni (una coda di candidati propria del tuo club, rinnovata regolarmente; una proposta non gestita scade). Ogni candidato appare come una carta con la sua stima di potenziale (Promessa, Grande promessa o Prodigio, vedi",
