  "de plus si le cinq de départ est le même qu'au match précédent. Sur une saison, un effectif stable gagne environ +40. Les interviews de jalon aussi : ton Humble +2 après une victoire, +1 après une défaite ; Mesuré +1 après une victoire.": "in più se il quintetto iniziale è lo stesso della partita precedente. In una stagione, una rosa stabile guadagna circa +40. Anche le interviste chiave: tono Umile +2 dopo una vittoria, +1 dopo una sconfitta; Misurato +1 dopo una vittoria.",
