  "Jusqu'à 150 000 €": "Fino a 150.000 €",
  "Jusqu'à 3 affectations poste + focus (empêcher le post-up, coller sur les pénétrations, harceler le tir extérieur, priorité au rebond, couper du ballon). Chaque focus donne un bonus défensif ciblé, avec une petite contrepartie ailleurs pour le défenseur concerné.": "Fino a 3 assegnazioni ruolo + focus (impedire il post-up, stare attaccati sulle penetrazioni, pressare il tiro da fuori, priorità al rimbalzo, anticipare sulla linea di passaggio). Ogni focus dà un bonus difensivo mirato, con un piccolo rovescio della medaglia altrove per il difensore interessato.",
  "Jusqu'à 300 000 €": "Fino a 300.000 €",
  "Jusqu'à 50 000 €": "Fino a 50.000 €",
  "Jusqu'où le joueur peut encore progresser, jamais en chiffre : un palier parmi 10, de Débutant à Générationnel (Prospect, Joueur correct, Solide, Starter, Très bon joueur, Star, All-Star, Superstar). Les jeunes de l'académie n'affichent qu'une estimation : Espoir, Grand espoir ou Prodige.": "Quanto il giocatore può ancora crescere, mai in cifre: un livello tra 10, da Esordiente a Generazionale (Prospetto, Giocatore discreto, Solido, Titolare, Ottimo giocatore, Stella, All-Star, Superstar). I giovani del vivaio mostrano solo una stima: Promessa, Grande promessa o Prodigio.",
