  "L'adversaire ne peut pas aligner un cinq de départ complet : vous gagnerez automatiquement par forfait (20-0) à l'heure prévue.": "L'avversario non può schierare un quintetto iniziale completo: vincerai automaticamente a tavolino (20-0) all'orario previsto.",
  "L’affiche": "Il match",
  "L'alchimie (0 à 100, visible sur le Tableau de bord et en tête de l'Effectif) mesure la cohésion du groupe. Elle agit sur TOUTE l'équipe en match, de -6 % (vestiaire fracturé) à +6 % (alchimie parfaite). Paliers : Vestiaire fracturé (moins de 25), Tensions dans le groupe (25-44), Cohésion correcte (45-64), Bonne cohésion (65-84), Alchimie parfaite (85 et plus).": "L'intesa (da 0 a 100, visibile nella Panoramica e in cima alla Rosa) misura la coesione del gruppo. Agisce su TUTTA la squadra in partita, da -6% (spogliatoio spaccato) a +6% (intesa perfetta). Livelli: Spogliatoio spaccato (meno di 25), Tensioni nel gruppo (25-44), Intesa discreta (45-64), Buona intesa (65-84), Intesa perfetta (85 e oltre).",
  "L'ambiance du club": "L'atmosfera del club",
  "L’attaque tourne à plein régime.": "L'attacco gira a pieno regime.",
  "L’AVANT-": "IL PRE",
  "L’AVANT-MATCH": "IL PREPARTITA",
  "L'effectif jeunes est déjà complet (15 stagiaires).": "La rosa giovanile è già al completo (15 ragazzi).",
  "L'émission de la mi-temps": "Il programma dell'intervallo",
  "l'emporte de": "vince di",
  "L'entraîneur n'a aucun effet sur les matchs : il accélère uniquement la progression à l'entraînement (+6% par niveau). On ne l'achète plus à prix fixe : plusieurs candidats de niveaux variés sont proposés en permanence sur un": "L'allenatore non ha alcun effetto sulle partite: accelera solo la crescita in allenamento (+6% per livello). Non si compra più a prezzo fisso: diversi candidati di livello variabile sono proposti in permanenza su un",
  "L'entre-deux est remporté par {0}.": "La palla a due è vinta da {0}.",
  "L'humeur des supporters (0 à 100, onglet dédié) influence le remplissage de votre salle et la tolérance au prix du billet : des supporters contents viennent plus facilement et acceptent des prix plus élevés. Elle évolue avec chaque résultat (victoire ou défaite, à domicile ou à l'extérieur), vos tons en interview de jalon, et dérive lentement selon que le prix des billets est jugé raisonnable ou non.": "L'umore dei tifosi (da 0 a 100, scheda dedicata) influenza il riempimento del palazzetto e la tolleranza al prezzo del biglietto: tifosi contenti vengono più volentieri e accettano prezzi più alti. Cambia con ogni risultato (vittoria o sconfitta, in casa o in trasferta), i toni scelti nelle interviste chiave, e deriva lentamente a seconda che il prezzo dei biglietti sia giudicato ragionevole o no.",
  "L'image de votre salle actuelle. Une salle plus grande accueille plus de spectateurs à chaque match à domicile, donc plus de recettes de billetterie.": "L'immagine del tuo palazzetto attuale. Un palazzetto più grande accoglie più spettatori a ogni partita in casa, quindi più incassi di biglietteria.",
  "L'objectif de saison": "L'obiettivo stagionale",
  "L'objectif est clair pour cette saison : on vise le haut de tableau, on ne se fixe aucune limite.": "L'obiettivo per questa stagione è chiaro: puntiamo alle prime posizioni, senza porci limiti.",
  "L'objectif est de construire une équipe solide et de rester compétitifs sur la durée de la saison, sans se fixer de chiffre précis pour l'instant.": "L'obiettivo è costruire una squadra solida e restare competitivi per tutta la stagione, senza fissare per ora un traguardo preciso.",
  "L'onglet": "La scheda",
  "La": "La",
  "La confiance du joueur, jamais liée à la fatigue. Alimentée par le ton choisi lors des interviews de jalon (voir l'onglet Humeur des supporters) : Agressif amplifie le résultat, Mesuré reste modéré, Humble limite la casse en cas de défaite.": "La fiducia del giocatore, mai legata alla stanchezza. Alimentata dal tono scelto nelle interviste chiave (vedi la scheda Umore dei tifosi): Aggressivo amplifica il risultato, Misurato resta moderato, Umile limita i danni in caso di sconfitta.",
  "La Coupe": "La Coppa",
  "La Coupe n'existe que pour la ligue multi-manager (elle n'est pas jouée en carrière solo pour l'instant).": "La Coppa esiste solo per la lega multi-manager (per ora non si gioca nella carriera singola).",
  "La courbe apparaîtra après le premier événement.": "La curva apparirà dopo il primo evento.",
  "La courbe du budget apparaîtra après la première semaine.": "La curva del budget apparirà dopo la prima settimana.",
