  "La feuille de match de l'adversaire est incomplète : vous gagnerez par forfait (20-0) si elle n'est pas réglée avant le coup d'envoi.": "La formazione dell'avversario è incompleta: vincerai a tavolino (20-0) se non viene sistemata prima della palla a due.",
