  "La liste des jeunes formés dans votre académie qui sont ensuite passés pro : un aperçu de ce que votre filière de formation a déjà produit pour le club.": "L'elenco dei giovani cresciuti nel tuo vivaio che sono poi passati professionisti: uno sguardo a ciò che il tuo settore giovanile ha già prodotto per il club.",
  "La plupart des joueurs se situent dans les paliers médians (Starter à All-Star) ; Superstar et Générationnel restent volontairement rares.": "La maggior parte dei giocatori si colloca nei livelli intermedi (da Titolare ad All-Star); Superstar e Generazionale restano volutamente rari.",
