  "Le": "Il",
  "Le barrage de relégation a été calculé. Les play-offs commencent, un match à la fois, en direct, sur plusieurs jours réels.": "Lo spareggio salvezza è stato calcolato. Iniziano i playoff, una partita alla volta, in diretta, su più giorni reali.",
  "Le calendrier": "Il calendario",
  "Le calendrier sera généré pour les clubs déjà inscrits.": "Il calendario sarà generato per i club già iscritti.",
  "Le centre de formation": "Il centro di formazione",
  "Le champion est désormais connu, direction l'écran de fin de saison.": "Il campione ora è noto, si passa alla schermata di fine stagione.",
  "Le championnat est lancé": "Il campionato è partito",
  "Le classement avant la journée": "La classifica prima della giornata",
  "Le classement s'affichera après les premiers matchs de championnat.": "La classifica apparirà dopo le prime partite di campionato.",
  "Le classement se départage par victoires puis par différence de points. Il est découpé en zones : places 1 à 4 qualifiées pour les": "La classifica si decide per vittorie e poi per differenza punti. È divisa in zone: posti da 1 a 4 qualificati per i",
  "Le classement se départage par victoires puis par différence de points. Places 1 à 4 : play-offs ; 5 et 6 : maintien ; 7 et 8 : barrage ; 9 et 10 : relégation. Ce panneau résume votre position et l'écart avec les places clés.": "La classifica si decide per vittorie e poi per differenza punti. Posti da 1 a 4: playoff; 5 e 6: salvezza; 7 e 8: spareggio; 9 e 10: retrocessione. Questo pannello riassume la tua posizione e il distacco dai posti chiave.",
  "Le club est en quasi-faillite (budget : {0}, sous {1} depuis {2} semaine(s)) : tout l'effectif a été mis en vente forcée à 1 €. Direction l'onglet": "Il club è sull'orlo del fallimento (budget: {0}, sotto {1} da {2} settimana/e): tutta la rosa è stata messa in vendita forzata a 1 €. Vai alla scheda",
  "Le club est entre vos mains. Bonne saison, coach.": "Il club è nelle tue mani. Buona stagione, coach.",
  "Le coup d'envoi est imminent.": "La palla a due è imminente.",
  "Le duel à suivre": "Il duello da seguire",
  "Le duel de la soirée : {a} contre {b}.": "Il duello della serata: {a} contro {b}.",
  "Le Hall of Fame est plein ({0} joueurs).": "La Hall of Fame è piena ({0} giocatori).",
  "Le joueur": "Il giocatore",
  "Le journal des événements": "Il registro degli eventi",
  "Le marché des transferts": "Il mercato dei trasferimenti",
  "Le match à suivre": "La partita da seguire",
  "le match précédent": "la partita precedente",
  "Le même Centre de formation que dans l'onglet Salle, mais géré directement ici : agrandissable palier par palier, il accélère la progression automatique de tous vos jeunes tant qu'ils ont moins de 18 ans.": "Lo stesso Centro di formazione della scheda Palazzetto, ma gestito direttamente qui: ampliabile livello per livello, accelera la crescita automatica di tutti i tuoi giovani finché hanno meno di 18 anni.",
  "Le moteur vise ces minutes et les ajuste seul en cas de blessure, de fautes ou de fatigue. Un poste en automatique garde la rotation habituelle.": "Il motore punta a questi minuti e li aggiusta da solo in caso di infortunio, falli o stanchezza. Un ruolo in automatico mantiene la rotazione abituale.",
  "Le n°1 en fin de saison gagne 1 mois de Premium": "Il n°1 a fine stagione vince 1 mese di Premium",
  "Le nom de la ligue doit faire entre 2 et {0} caractères.": "Il nome della lega deve avere tra 2 e {0} caratteri.",
  "Le nom de la salle contient des caractères non autorisés.": "Il nome del palazzetto contiene caratteri non consentiti.",
  "Le nom de la salle doit faire entre 3 et {0} caractères.": "Il nome del palazzetto deve avere tra 3 e {0} caratteri.",
  "Le nom et la capacité de votre salle actuelle, avec un bouton Agrandir pour passer au palier suivant quand vous en avez les moyens (8 paliers en tout, du Petit gymnase à l'Arena nationale).": "Il nome e la capienza del tuo palazzetto attuale, con un pulsante Amplia per passare al livello successivo quando te lo puoi permettere (8 livelli in tutto, dalla Piccola palestra all'Arena nazionale).",
  "Le numéro {0} est déjà retiré.": "Il numero {0} è già ritirato.",
  "Le poste de {poste} est désormais pourvu.": "Il ruolo di {poste} è ora coperto.",
  "Le potentiel indique jusqu'où un joueur peut encore progresser, pas sa qualité du moment. Il ne s'affiche jamais en chiffre : seulement un": "Il potenziale indica fin dove un giocatore può ancora crescere, non la sua qualità attuale. Non si mostra mai in cifre: solo un",
  "Le prix des billets se règle depuis l'onglet Salle, pas ici : ajustez-le pour équilibrer affluence et recettes.": "Il prezzo dei biglietti si imposta dalla scheda Palazzetto, non qui: regolalo per bilanciare affluenza e incassi.",
  "Le roster complet du club en une seule liste, cinq de départ en tête, puis rotation et réserve : poste, potentiel, âge, salaire, forme, motivation et évaluation des derniers matchs. Cliquez sur un nom pour ouvrir la fiche du joueur (caractéristiques, saison, Comparer, Vendre).": "La rosa completa del club in un'unica lista, quintetto iniziale in testa, poi rotazione e riserve: ruolo, potenziale, età, stipendio, forma, motivazione e valutazione delle ultime partite. Clicca su un nome per aprire la scheda del giocatore (caratteristiche, stagione, Confronta, Vendi).",
  "Le serveur a refusé ce nom.": "Il server ha rifiutato questo nome.",
