  "Le travail à l'entraînement toute la semaine a payé ce soir, je suis content d'avoir pu répondre présent.": "Il lavoro in allenamento di tutta la settimana ha pagato stasera, sono contento di aver risposto presente.",
  "Le trigramme doit faire 2 ou 3 lettres (A-Z).": "La sigla deve avere 2 o 3 lettere (A-Z).",
  "Le vrai potentiel d'un jeune reste caché derrière une estimation à 3 paliers jusqu'à sa promotion : la décision comporte donc une part de pari.": "Il vero potenziale di un giovane resta nascosto dietro una stima a 3 livelli fino alla promozione: la decisione comporta quindi una parte di scommessa.",
