  "Les ligues privées n'existent que dans la ligue partagée entre managers (pas en carrière solo).": "Le leghe private esistono solo nella lega condivisa tra manager (non nella carriera singola).",
  "Les ligues privées ne sont disponibles que dans la ligue partagée.": "Le leghe private sono disponibili solo nella lega condivisa.",
  "Les ligues privées sont réservées aux clubs Premium.": "Le leghe private sono riservate ai club Premium.",
  "Les noms de club doivent être uniques.": "I nomi dei club devono essere unici.",
  "Les ordres de Coupe se préparent comme ceux du championnat, depuis le Calendrier ou le sélecteur de journée de l'onglet Ordres.": "Gli ordini di Coppa si preparano come quelli del campionato, dal Calendario o dal selettore della giornata della scheda Ordini.",
  "Les play-offs sont en cours, sur plusieurs jours réels. Revenez pour votre prochain match, ou suivez leur progression ici.": "I playoff sono in corso, su più giorni reali. Torna per la tua prossima partita, o segui qui il loro andamento.",
  "Les play-offs vont commencer.": "I playoff stanno per cominciare.",
  "Les records s'écriront dès le premier match joué.": "I record si scriveranno dalla prima partita giocata.",
  "Le poste d'un joueur suit ses caractéristiques : dès que sa note à un autre poste dépasse nettement celle de son poste actuel, il change de poste (une nouvelle vous prévient). Les salaires (masse salariale visible sur l'onglet": "Il ruolo di un giocatore segue le sue caratteristiche: appena la sua valutazione in un altro ruolo supera nettamente quella del ruolo attuale, cambia ruolo (una notizia ti avvisa). Gli stipendi (monte ingaggi visibile nella scheda",
  "Les sponsors reviennent tous les 3 jours. Une meilleure réputation attire de plus grandes marques.": "Gli sponsor tornano ogni 3 giorni. Una reputazione migliore attira marchi più grandi.",
  "Les statistiques de ligue privée ne comptent ni dans les stats de carrière ni dans le classement des joueurs.": "Le statistiche delle leghe private non contano né nelle statistiche di carriera né nella classifica dei giocatori.",
