  "liste tous vos matchs de la saison, championnat et Coupe confondus, groupés par mois et triés par date et heure réelle. Filtres Tous, Domicile, Extérieur et À venir ; \"vs\" devant l'adversaire signifie à domicile, \"@\" à l'extérieur. À droite : la carte du prochain match (compte à rebours et bouton des ordres) et le bilan de la saison (bilan, classement, différence de points, domicile/extérieur, forme sur les 5 derniers matchs). Les horaires restent fixes, même au changement d'heure.": "elenca tutte le tue partite della stagione, campionato e Coppa insieme, raggruppate per mese e ordinate per data e ora reali. Filtri Tutte, Casa, Trasferta e In arrivo; \"vs\" davanti all'avversario significa in casa, \"@\" in trasferta. A destra: il riquadro della prossima partita (conto alla rovescia e pulsante degli ordini) e il bilancio della stagione (bilancio, classifica, differenza punti, casa/trasferta, forma nelle ultime 5 partite). Gli orari restano fissi, anche al cambio dell'ora legale.",
