  "MENTAL": "MENTALE",
  "Mental, Endurance, Lancer franc, Puissance, Concentration, Anticipation et Leadership alimentent chacune un mécanisme de match dédié. Le Mental améliore la réussite au tir dans le money time et limite les dégâts d'une mauvaise série. L'Endurance ralentit la fatigue EN MATCH du joueur. Le Lancer franc détermine directement la réussite aux lancers francs, la Concentration l'améliore encore un peu. La Puissance augmente les fautes provoquées près du panier. L'Anticipation renforce la pression défensive de toute l'équipe sur les extérieurs. Le Leadership du MEILLEUR joueur du cinq en jeu allège, pour toute l'équipe, le malus d'une mauvaise série de tirs manqués.": "Mentale, Resistenza, Tiro libero, Potenza, Concentrazione, Anticipo e Leadership alimentano ciascuna un meccanismo di gioco dedicato. Il Mentale migliora la precisione al tiro nel money time e limita i danni di una serie negativa. La Resistenza rallenta la stanchezza IN PARTITA del giocatore. Il Tiro libero determina direttamente la precisione ai liberi, e la Concentrazione la migliora ancora un po'. La Potenza aumenta i falli subiti vicino al canestro. L'Anticipo rafforza la pressione difensiva di tutta la squadra sugli esterni. La Leadership del MIGLIOR giocatore del quintetto in campo attenua, per tutta la squadra, il malus di una serie di tiri sbagliati.",
