  "On a fait la moitié du chemin avec cette victoire contre {opponent}, mais rien n'est acquis, il reste encore beaucoup de travail avant la fin de saison.": "Siamo a metà strada con questa vittoria contro {opponent}, ma niente è acquisito, c'è ancora tanto lavoro prima della fine della stagione.",
  "On aborde la suite avec humilité, chaque adversaire mérite le plus grand respect à ce stade de la saison.": "Affrontiamo il seguito con umiltà, ogni avversario merita il massimo rispetto a questo punto della stagione.",
  "On aborde la suite avec l'envie de corriger ce qui n'a pas fonctionné ces dernières semaines.": "Affrontiamo il seguito con la voglia di correggere ciò che non ha funzionato nelle ultime settimane.",
  "On aborde la suite avec la certitude d'avoir le niveau pour aller loin, sans aucune pression particulière.": "Affrontiamo il seguito con la certezza di avere il livello per andare lontano, senza alcuna pressione particolare.",
  "On aborde la suite avec la même confiance, cette fin de saison régulière ne change rien à nos ambitions.": "Affrontiamo il seguito con la stessa fiducia, questo finale di stagione regolare non cambia nulla alle nostre ambizioni.",
  "On aborde la suite en sachant qu'il reste beaucoup de travail, on ne change rien à notre état d'esprit.": "Affrontiamo il seguito sapendo che c'è ancora molto lavoro da fare, non cambiamo il nostro stato d'animo.",
  "On aborde la suite sereinement, en essayant de garder cette dynamique le plus longtemps possible.": "Affrontiamo il seguito con serenità, cercando di mantenere questo slancio il più a lungo possibile.",
  "On accepte cette élimination avec humilité et on va travailler encore plus dur pour revenir plus forts.": "Accettiamo questa eliminazione con umiltà e lavoreremo ancora più duro per tornare più forti.",
  "On cherche un partenaire stable, pas un feu de paille.": "Cerchiamo un partner stabile, non un fuoco di paglia.",
  "On compte énormément sur {player} pour tirer l'équipe vers le haut, c'est un joueur fait pour ce genre de responsabilités.": "Contiamo moltissimo su {player} per trascinare la squadra verso l'alto, è un giocatore fatto per questo tipo di responsabilità.",
  "On doit se remettre en question collectivement et travailler encore plus dur pour la seconde moitié de saison.": "Dobbiamo metterci in discussione collettivamente e lavorare ancora più duro per la seconda metà di stagione.",
  "On envoie un message clair à toute la ligue en éliminant {opponent} en demi-finale, la prochaine étape ne nous fait absolument pas peur.": "Mandiamo un messaggio chiaro a tutta la lega eliminando {opponent} in semifinale, il prossimo passo non ci fa assolutamente paura.",
  "On ne se fixe pas d'objectif chiffré, l'idée est de progresser ensemble match après match, en restant les pieds sur terre.": "Non ci fissiamo un obiettivo in cifre, l'idea è crescere insieme partita dopo partita, restando con i piedi per terra.",
  "On passe le cap de la mi-saison sur la meilleure dynamique possible, et {opponent} vient encore de le confirmer : personne ne veut vraiment nous affronter en ce moment.": "Superiamo il giro di boa della stagione nel miglior momento possibile, e {opponent} lo ha appena confermato ancora una volta: nessuno vuole davvero affrontarci in questo momento.",
  "On prépare la suite avec la même confiance, on n'a pas fait tout ce chemin pour s'arrêter en si bon chemin.": "Prepariamo il seguito con la stessa fiducia, non abbiamo fatto tutta questa strada per fermarci proprio ora.",
  "On savait qu'on était la meilleure équipe de la division, ce titre face à {opponent} en finale ne fait que le confirmer.": "Sapevamo di essere la squadra migliore della divisione, questo titolo contro {opponent} in finale non fa che confermarlo.",
  "On se retrouve après une courte pause…": "Ci ritroviamo dopo una breve pausa…",
  "On termine la saison régulière sur cette victoire contre {opponent}, et on aborde les échéances qui arrivent avec la plus grande confiance qui soit.": "Chiudiamo la stagione regolare con questa vittoria contro {opponent}, e affrontiamo gli appuntamenti in arrivo con la massima fiducia.",
  "On termine la saison régulière sur une défaite décevante contre {opponent}, mais le bilan global de l'année reste ce qui compte le plus.": "Chiudiamo la stagione regolare con una sconfitta deludente contro {opponent}, ma il bilancio complessivo dell'anno è ciò che conta di più.",
  "On tire un trait sur cette élimination et on prépare déjà la revanche pour la saison prochaine, sans complexe.": "Mettiamo una pietra sopra questa eliminazione e prepariamo già la rivincita per la prossima stagione, senza complessi.",
  "On va analyser calmement cette élimination et en tirer les enseignements pour progresser encore.": "Analizzeremo con calma questa eliminazione e ne trarremo insegnamenti per crescere ancora.",
  "On va continuer à travailler dans la continuité, avec quelques ajustements tactiques pour la seconde moitié.": "Continueremo a lavorare nella continuità, con qualche ritocco tattico per la seconda metà.",
  "On va continuer à travailler humblement, rien n'est jamais acquis dans ce championnat.": "Continueremo a lavorare con umiltà, niente è mai acquisito in questo campionato.",
  "On va préparer la suite avec sérieux, sans s'enflammer, il reste encore une marche à franchir.": "Prepareremo il seguito con serietà, senza esaltarci, c'è ancora un gradino da salire.",
  "On va préparer la suite pas à pas, sans se projeter trop vite sur la suite.": "Prepareremo il seguito passo dopo passo, senza guardare troppo avanti.",
  "On va revoir certains détails à l'entraînement pour repartir sur de meilleures bases en seconde moitié de saison.": "Rivedremo alcuni dettagli in allenamento per ripartire su basi migliori nella seconda metà di stagione.",
  "On veut vous voir plus haut que ce que le CA demande.": "Vogliamo vederti più in alto di quanto chiede il CdA.",
  "On vous suit sur l'objectif de la saison.": "Ti seguiamo sull'obiettivo stagionale.",
