  "penetration": "penetration",
  "Pénétration": "Penetrazione",
  "Pénétration, Création de tir, Interceptions, Vitesse, Accélération, Force, Détente, Décision, Sang-froid, Détermination, Discipline et Vision ont elles aussi leur mécanisme. La Pénétration aide à se créer un accès à la raquette. La Création de tir est le facteur principal de la qualité d'ouverture d'un tir. Les Interceptions pèsent dans le choix du voleur de balle. La Vitesse et l'Accélération déclenchent des contre-attaques et aident à battre son défenseur au premier pas. La Force et la Détente renforcent le rebond et le contre. La Décision réduit les pertes de balle ; la Vision améliore le choix du passeur. Le Sang-froid et la Détermination agissent comme le Mental. La Discipline réduit les fautes en défense ; un défenseur peu discipliné risque une faute antisportive, un défenseur peu serein une faute technique : deux techniques, deux antisportives, ou une de chaque dans le même match valent exclusion.": "Anche Penetrazione, Creazione del tiro, Palle rubate, Velocità, Accelerazione, Forza, Elevazione, Decisioni, Sangue freddo, Determinazione, Disciplina e Visione hanno il loro meccanismo. La Penetrazione aiuta a crearsi un accesso all'area. La Creazione del tiro è il fattore principale della qualità di un tiro aperto. Le Palle rubate pesano nella scelta di chi ruba palla. Velocità e Accelerazione innescano i contropiedi e aiutano a battere il difensore sul primo passo. Forza ed Elevazione rafforzano rimbalzo e stoppata. Le Decisioni riducono le palle perse; la Visione migliora la scelta del passatore. Sangue freddo e Determinazione agiscono come il Mentale. La Disciplina riduce i falli in difesa; un difensore poco disciplinato rischia un fallo antisportivo, un difensore poco sereno un fallo tecnico: due tecnici, due antisportivi o uno di ciascuno nella stessa partita valgono l'espulsione.",
