  "Places libres après vos enchères": "Posti liberi dopo le tue offerte",
  "Chaque poste a sa carte sur le terrain : titulaire, remplaçant et réserviste. Les alertes (joueur hors poste, remplaçant plus fort que le titulaire, joueur aligné à deux postes) s'affichent directement sur la carte, et la liste de l'effectif à côté sert à convoquer les 12 joueurs du match.": "Ogni ruolo ha la sua carta sul campo: titolare, riserva e riservista. Gli avvisi (giocatore fuori ruolo, riserva più forte del titolare, giocatore schierato in due ruoli) appaiono direttamente sulla carta, e l'elenco della rosa accanto serve a convocare i 12 giocatori della partita.",
