  "Récapitulatif semaine par semaine de votre club : matchs joués et performances individuelles de l'effectif. Naviguez d'une semaine à l'autre avec les flèches en haut de la page. Les finances sont dans l'onglet Économie, l'humeur des supporters dans son propre onglet.": "Riepilogo settimana per settimana del tuo club: partite giocate e prestazioni individuali della rosa. Passa da una settimana all'altra con le frecce in cima alla pagina. Le finanze sono nella scheda Economia, l'umore dei tifosi nella sua scheda.",
