  "Recherche par poste, âge, potentiel, prix (dont \"dans mon budget\") et jusqu'à 5 critères de caractéristiques, avec plusieurs tris (fin d'enchère, note, potentiel, meilleure affaire, prix, âge). Chaque annonce affiche la note du joueur, ses points forts, une": "Ricerca per ruolo, età, potenziale, prezzo (incluso \"nel mio budget\") e fino a 5 criteri sulle caratteristiche, con diversi ordinamenti (fine asta, valutazione, potenziale, affare migliore, prezzo, età). Ogni annuncio mostra la valutazione del giocatore, i suoi punti di forza, una",
