  "Réduit la fatigue accumulée par vos joueurs au fil des matchs et des entraînements. Même principe que la salle de musculation : plusieurs paliers payants.": "Riduce la stanchezza accumulata dai tuoi giocatori tra partite e allenamenti. Stesso principio della sala pesi: diversi livelli a pagamento.",
  "Réduit le risque de blessure de vos joueurs. Plusieurs paliers payants au-delà du niveau de base, chacun un cran plus efficace que le précédent.": "Riduce il rischio di infortunio dei tuoi giocatori. Diversi livelli a pagamento oltre il livello base, ognuno un gradino più efficace del precedente.",
