  "Réinitialiser TOUTE la ligue partagée ? Cette action efface le calendrier, le classement, la Coupe et les effectifs de TOUS les managers (pas seulement le tien) et ne peut pas être annulée.": "Reimpostare TUTTA la lega condivisa? Questa azione cancella il calendario, la classifica, la Coppa e le rose di TUTTI i manager (non solo la tua) e non può essere annullata.",
