  "La réputation du club auprès du public, bâtie sur les 5 dernières saisons : la division d'abord, puis le classement, les play-offs, la coupe et les montées. La saison la plus récente compte le plus. Mis à jour à chaque changement de saison.": "La reputazione del club presso il pubblico, costruita sulle ultime 5 stagioni: prima la divisione, poi la classifica, i play-off, la coppa e le promozioni. La stagione più recente conta di più. Aggiornato a ogni cambio di stagione.",
