  "Toute l'équipe devra apporter sa pierre à l'édifice, mais {player} aura un rôle important à jouer pour nous aider à progresser.": "Tutta la squadra dovrà dare il suo contributo, ma {player} avrà un ruolo importante per aiutarci a crescere.",
