  "Vient de fêter ses 18 ans : décision requise. Sans décision avant la saison prochaine, il sera automatiquement libéré.": "Ha appena compiuto 18 anni: decisione richiesta. Senza decisione prima della prossima stagione, sarà svincolato automaticamente.",
