  "Volume": "Volume",
  "Votre club n'est plus engagé en Coupe cette saison (déjà éliminé, ou éliminé avant même d'avoir pu jouer).": "Il tuo club non è più in Coppa in questa stagione (già eliminato, o eliminato prima ancora di poter giocare).",
  "Votre club ne fait pas partie de cette ligue privée.": "Il tuo club non fa parte di questa lega privata.",
  "Votre club participe déjà à une ligue privée.": "Il tuo club partecipa già a una lega privata.",
  "Votre effectif": "La tua rosa",
  "votre enchère": "la tua offerta",
  "Votre équipe": "La tua squadra",
  "Votre équipe maîtrise plus ou moins chaque option tactique : une jauge par priorité offensive, par défense et par rythme (visible dans le menu \"Aspect travaillé\" de l'Entraînement). La maîtrise des options que vous jouez agit sur toute l'équipe en match, jusqu'à +/-6 %, en plus de l'alchimie.": "La tua squadra padroneggia più o meno ogni opzione tattica: un indicatore per priorità offensiva, per difesa e per ritmo (visibile nel menu \"Aspetto allenato\" dell'Allenamento). La padronanza delle opzioni che giochi agisce su tutta la squadra in partita, fino a +/-6%, in aggiunta all'intesa.",
  "Votre offre": "La tua offerta",
  "Votre partie arrive...": "La tua partita sta arrivando...",
