  "(un seul par club) : il s'achète aussi sur ce marché. Chaque candidat a une spécialité :": "(uno solo per club): si compra anche lui su questo mercato. Ogni candidato ha una specialità:",
  "tir": "tiro",
  "défense": "difesa",
  "(tir à 3 points, mi-distance, lancer franc),": "(tiro da 3 punti, media distanza, tiro libero),",
  "meneurs": "esterni",
  "(dribble, passe, création de tir, pénétration),": "(palleggio, passaggio, creazione del tiro, penetrazione),",
  "intérieurs": "lunghi",
  "(jeu intérieur, rebond, contre, défense intérieure) ou": "(gioco interno, rimbalzo, stoppata, difesa interna) o",
  "(défense extérieure, interceptions). Chaque semaine, tous les joueurs non blessés progressent un peu sur ces caractéristiques, qu'ils aient joué ou non, en plus de l'entraînement des fondamentaux. Moins sa spécialité compte de caractéristiques, plus chacune progresse vite. L'effet est surtout sensible chez les jeunes, il dépend aussi du poste et du gabarit de chaque joueur, et il est renforcé par l'entraîneur principal.": "(difesa perimetrale, palle rubate). Ogni settimana, tutti i giocatori non infortunati migliorano un po' in queste caratteristiche, che abbiano giocato o no, in aggiunta all'allenamento dei fondamentali. Meno caratteristiche comprende la sua specialità, più in fretta migliora ciascuna. L'effetto si sente soprattutto nei giovani, dipende anche dal ruolo e dalla stazza di ogni giocatore, ed è rafforzato dall'allenatore principale.",
  "Entraîneur, entraîneur adjoint, analyste vidéo, recruteur, médecin, kiné : chacun a 5 niveaux, avec un coût et un effet croissants. L'analyste vidéo révèle par exemple certaines caractéristiques cachées des joueurs adverses avant un match, et le kiné réduit le risque de blessure.": "Allenatore, vice allenatore, video analista, osservatore, medico, fisioterapista: ognuno ha 5 livelli, con costo ed effetto crescenti. Il video analista, per esempio, rivela alcune caratteristiche nascoste dei giocatori avversari prima di una partita, e il fisioterapista riduce il rischio di infortunio.",
  "staff médical": "staff medico",
  "s'achète sur le même marché aux enchères, avec le même salaire qui grimpe chaque semaine. Le": "si compra sullo stesso mercato ad asta, con lo stesso stipendio che sale ogni settimana. Il",
  "raccourcit la durée des nouvelles blessures. Le": "accorcia la durata dei nuovi infortuni. Il",
  "suit tout l'effectif : la forme physique remonte plus vite chaque jour et le risque de blessure en match baisse (il s'ajoute à l'effet de la salle de musculation). Plus leur niveau est élevé, plus l'effet est fort.": "segue tutta la rosa: la condizione fisica risale più in fretta ogni giorno e il rischio di infortunio in partita scende (si aggiunge all'effetto della sala pesi). Più alto è il loro livello, più forte è l'effetto.",
