  "Champion de sa ligue, {0} jouera en {1} la saison prochaine. Profitez de l'intersaison pour renforcer l'effectif.": "Campione della sua lega, {0} giocherà in {1} la prossima stagione. Approfitta della pausa estiva per rinforzare la rosa.",
