  "Montées et descentes": "Promozioni e retrocessioni",
  ", décidées le lundi d'intersaison et appliquées à la reprise : le champion des play-offs de chaque championnat monte ; en face, le 10e descend, puis le 9e, puis le perdant du barrage (7e contre 8e), autant qu'il y a de championnats ouverts juste en dessous. Une prime de montée est versée au club promu.": ", decise il lunedì della pausa estiva e applicate alla ripresa: la vincitrice dei playoff di ogni campionato sale; di contro scende la 10ª, poi la 9ª, poi la perdente dello spareggio (7ª contro 8ª), tante quante sono i campionati aperti subito sotto. Al club promosso viene versato un premio promozione.",
  "(en bas du menu) : choisissez un pays (le vôtre par défaut) pour voir ses divisions ouvertes, son palmarès et les meilleurs joueurs de la saison. Pour afficher un autre championnat ou un club, tapez son nom dans la barre de recherche du haut (« II.2 », « Division III », un nom de club…) : classement, derniers résultats et effectif en lecture seule.": "(in fondo al menu): scegli un paese (il tuo per impostazione predefinita) per vedere le sue divisioni aperte, il suo albo d'oro e i migliori giocatori della stagione. Per mostrare un altro campionato o un club, scrivi il suo nome nella barra di ricerca in alto (« II.2 », « Divisione III », il nome di un club…): classifica, ultimi risultati e rosa in sola lettura.",
