  // Coupe nationale (2026-09-28).
  "Coupe nationale": "Coppa nazionale",
  "Dans les championnats par pays, c'est la": "Nei campionati per paese, è la",
  ": tous les clubs du pays (512 au plus), avec des exempts au premier tour pour les divisions les plus hautes si le tableau n'est pas plein. Le club de la division inférieure part avec": ": tutti i club del paese (512 al massimo), con esenzioni al primo turno per le divisioni più alte se il tabellone non è pieno. Il club della divisione inferiore parte con",
  "+7 points par division d'écart": "+7 punti per ogni divisione di differenza",
  "(au plus +21), déjà au tableau d'affichage. Un adversaire d'un autre championnat se prépare comme les autres (Ordres, scouting) et sa fiche s'ouvre dans Planète Hoop. Chaque match de Coupe gagné rapporte une prime, de 50 000 € aux premiers tours à 400 000 € pour la finale. À l'intersaison, la": "(al massimo +21), già sul tabellone. Un avversario di un altro campionato si prepara come gli altri (Ordini, scouting) e la sua scheda si apre in Pianeta Hoop. Ogni partita di Coppa vinta porta un premio, da 50.000 € nei primi turni a 400.000 € per la finale. Durante la pausa estiva, la",
  "oppose le samedi à 20:00 le champion de Division I au vainqueur de la Coupe (ou au finaliste si c'est le même club), en direct et avec le même handicap : 200 000 € pour le vainqueur.": "mette di fronte il sabato alle 20:00 il campione di Divisione I e la vincitrice della Coppa (o la finalista se è lo stesso club), in diretta e con lo stesso handicap: 200.000 € alla vincitrice.",
  "Coupe nationale · {0} · saison {1} : tous les clubs du pays, un tour chaque jeudi. Le club de division inférieure part avec": "Coppa nazionale · {0} · stagione {1}: tutti i club del paese, un turno ogni giovedì. Il club di divisione inferiore parte con",
  "(au plus +21), compris dans les scores.": "(al massimo +21), compreso nei punteggi.",
