  "True shooting, réussite effective, stats par 36 minutes, +/- de la saison, et export du tableau en CSV (onglet Statistiques).": "True shooting, percentuale effettiva, statistiche per 36 minuti, +/- della stagione ed esportazione della tabella in CSV (scheda Statistiche).",
  "Revoir le direct": "Rivedi la diretta",
  "Rejouer le direct de vos matchs déjà joués, depuis leur feuille de statistiques (60 derniers matchs du championnat).": "Rivedi la diretta delle tue partite già giocate, dal loro tabellino (ultime 60 partite del campionato).",
  "Une notification de votre navigateur (ou de l'application installée sur votre téléphone) quand votre match commence, qu'un joueur se blesse ou qu'une de vos enchères (joueur ou staff) se termine.": "Una notifica del browser (o dell'app installata sul telefono) quando inizia la tua partita, quando un giocatore si infortuna o quando una delle tue aste (giocatore o staff) si chiude.",
