  "Coup d'envoi de vos matchs, blessures, fins d'enchère : réservé au Premium.": "Palla a due delle tue partite, infortuni, aste in chiusura: riservato al Premium.",
  "Les notifications ne sont pas encore disponibles sur ce serveur.": "Le notifiche non sono ancora disponibili su questo server.",
  "Ce navigateur ne gère pas les notifications. Sur iPhone, ajoute d'abord le jeu à l'écran d'accueil (Partager → Sur l'écran d'accueil).": "Questo browser non gestisce le notifiche. Su iPhone, aggiungi prima il gioco alla schermata Home (Condividi → Aggiungi alla schermata Home).",
  "Coup d'envoi de vos matchs, blessures, arrivées et départs, et vos enchères (joueurs et staff) : fin dans moins d'une heure, puis remportée ou perdue.": "Palla a due delle tue partite, infortuni, arrivi e partenze, e le tue aste (giocatori e staff): chiusura tra meno di un'ora, poi vinta o persa.",
