  // Managers inactifs (2026-09-28).
  "Longue absence": "Lunga assenza",
  ": sans aucune visite pendant 45 jours, votre club est confié à l'IA (effectif, nom et palmarès conservés). Reconnectez-vous à votre compte pour le récupérer, s'il n'a pas été repris entre-temps par un autre manager ; sinon un nouveau club vous est attribué.": ": senza nessuna visita per 45 giorni, il tuo club viene affidato all'IA (rosa, nome e palmarès conservati). Accedi di nuovo al tuo account per riprenderlo, se nel frattempo non l'ha preso un altro manager; altrimenti ti viene assegnato un nuovo club.",
  "Bon retour à {0} !": "Bentornato al {0}!",
  "Pendant votre absence, le club a été géré par l'IA. Vérifiez votre effectif, vos ordres et votre budget.": "Durante la tua assenza, il club è stato gestito dall'IA. Controlla la rosa, gli ordini e il budget.",
  // Amicaux entre championnats (2026-09-28).
  "Contre un club d'un autre championnat": "Contro un club di un altro campionato",
  ", même d'un autre pays : tapez son nom dans la recherche d'adversaire, les clubs du monde entier apparaissent sous ceux de votre ligue (drapeau et division). Mêmes règles : jour de repos des deux clubs, heure de Paris, invitation à accepter contre un manager (il est prévenu dans son fil d'actualité).": ", anche di un altro paese: scrivi il suo nome nella ricerca dell'avversario, i club di tutto il mondo compaiono sotto quelli della tua lega (bandiera e divisione). Stesse regole: giorno di riposo per entrambi i club, ora di Parigi, invito da accettare contro un manager (viene avvisato nelle sue notizie).",
  "Club d'un autre championnat ({0}) : l'amical se joue à la même heure (Paris) pour les deux clubs.": "Club di un altro campionato ({0}): l'amichevole si gioca alla stessa ora (Parigi) per entrambi i club.",
  "Autre championnat": "Altro campionato",
  "Un des deux clubs a changé de championnat.": "Uno dei due club ha cambiato campionato.",
  "Adversaire du même championnat : passez par la liste habituelle.": "Avversario dello stesso campionato: usa la lista abituale.",
  // Marché mondial (2026-09-28).
  "Monde entier": "Tutto il mondo",
  "Mon pays": "Il mio paese",
  "Mon championnat": "Il mio campionato",
  "Marché mondial": "Mercato mondiale",
  ": les annonces de tous les championnats, dans tous les pays, apparaissent aussi (drapeau et division du vendeur sur la carte ; filtre « Monde entier », « Mon pays » ou « Mon championnat »). On y enchérit de la même façon ; le joueur rejoint votre club à la clôture de l'enchère. Les annonces des autres championnats se mettent à jour toutes les quelques minutes : si quelqu'un a surenchéri entre-temps, votre enchère est refusée et le prix actualisé.": ": compaiono anche gli annunci di tutti i campionati, in tutti i paesi (bandiera e divisione del venditore sulla carta; filtro « Tutto il mondo », « Il mio paese » o « Il mio campionato »). Si fanno offerte allo stesso modo; il giocatore arriva nel tuo club alla chiusura dell'asta. Gli annunci degli altri campionati si aggiornano ogni pochi minuti: se nel frattempo qualcuno ha rilanciato, la tua offerta viene rifiutata e il prezzo aggiornato.",
  "Voir la Supercoupe": "Vedi la Supercoppa",
  "Supercoupe · saison {0} · champion de Division I contre vainqueur de la Coupe": "Supercoppa · stagione {0} · campione di Divisione I contro vincitore della Coppa",
