  "À la fin de la saison régulière, la ligue décerne ses": "Alla fine della stagione regolare, la lega assegna i suoi",
  "récompenses": "premi",
  ": MVP, 5 majeur (un joueur par poste), meilleur jeune (21 ans ou moins), 6e homme (un joueur surtout remplaçant) et meilleur défenseur, puis le": ": MVP, quintetto ideale (un giocatore per ruolo), miglior giovane (21 anni o meno), sesto uomo (un giocatore che parte soprattutto dalla panchina) e miglior difensore, poi l'",
  "(dans l'équipe championne) après la finale. Elles se calculent sur la saison régulière, pour les joueurs qui ont disputé au moins 40 % des journées, et s'affichent dans l'onglet Ligue.": "(della squadra campione) dopo la finale. Si calcolano sulla stagione regolare, per i giocatori che hanno disputato almeno il 40% delle giornate, e sono mostrati nella scheda Lega.",
  "À mi-saison, le dimanche à 20h, les 10 meilleurs joueurs du pays affrontent les 10 meilleurs étrangers lors du": "A metà stagione, la domenica alle 20, i 10 migliori giocatori del paese affrontano i 10 migliori stranieri nell'",
  ", un match d'exhibition sans effet sur le classement ni sur la forme. La fiche de chaque joueur montre sa nationalité et sa": ", una partita di esibizione senza effetti sulla classifica né sulla forma. La scheda di ogni giocatore mostra la sua nazionalità e la sua",
