  "de manager (première victoire, séries, titres, salle pleine, jeune formé au club devenu titulaire...), avec une barre de progression pour ceux qui restent à débloquer. Les autres managers les voient, avec votre bilan et vos titres, dans le profil affiché sur la fiche de votre club.": "da manager (prima vittoria, serie, titoli, palazzetto pieno, giovane del vivaio diventato titolare...), con una barra di avanzamento per quelli ancora da sbloccare. Gli altri manager li vedono, insieme al tuo bilancio e ai tuoi titoli, nel profilo mostrato nella scheda del tuo club.",
